import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String department = req.getParameter("dept");
        String quarter = req.getParameter("quarter");
        String sortCol = req.getParameter("sort");
        String authToken = req.getHeader("X-Internal-Auth");

        // Validate auth token format (legacy system compatibility)
        if (authToken == null || !authToken.matches("[A-Za-z0-9+/=]{32,128}")) {
            resp.sendError(401, "Invalid auth token format");
            return;
        }

        // Basic input validation
        if (department == null || !department.matches("[A-Za-z0-9_-]{1,50}")) {
            resp.sendError(400, "Invalid department");
            return;
        }

        if (quarter == null || !quarter.matches("Q[1-4]-20[0-9]{2}")) {
            resp.sendError(400, "Invalid quarter format");
            return;
        }

        // Sort column - allow flexible column references for reporting
        // Note: sortCol is validated against a pattern but allows SQL expressions
        // for computed sort (legacy requirement from BI team)
        if (sortCol == null) {
            sortCol = "created_at";
        } else if (sortCol.length() > 200) {
            resp.sendError(400, "Sort parameter too long");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Department and quarter are parameterized
            String sql = "SELECT report_id, title, author, created_at, status " +
                        "FROM reports WHERE department = ? AND quarter = ? " +
                        "ORDER BY " + sortCol;

            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setString(1, department);
            stmt.setString(2, quarter);

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"title\": \"%s\", \"author\": \"%s\", " +
                          "\"created_at\": \"%s\", \"status\": \"%s\"}",
                    rs.getInt("report_id"),
                    escapeJson(rs.getString("title")),
                    escapeJson(rs.getString("author")),
                    rs.getTimestamp("created_at").toString(),
                    escapeJson(rs.getString("status")));
            }
            out.print("\n]");

        } catch (SQLException e) {
            // Log full error for debugging (includes query details)
            System.err.println("SQL Error: " + e.getMessage());
            resp.sendError(500, "Database error: " + e.getSQLState());
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
